<template>
  <q-card class="login-activity-card">
    <q-card-section>
      <div class="row items-center justify-between q-mb-md">
        <div class="text-subtitle1 text-weight-medium card-title">
          <q-icon name="show_chart" class="q-mr-sm" />
          {{ $t('login_activity') }}
        </div>
      </div>

      <div class="chart-container">
        <div v-if="loading" class="chart-loader">
          <q-spinner-dots color="primary" size="50px" />
        </div>
        <div v-else-if="error" class="chart-error text-center text-grey-6">
          <q-icon name="warning" size="32px" class="q-mb-sm" />
          <div>{{ error }}</div>
        </div>
        <div v-else-if="hasNoData" class="chart-no-data text-center text-grey-6">
          <q-icon name="insert_chart_outlined" size="48px" class="q-mb-sm" />
          <div>{{ $t('no_login_data') }}</div>
        </div>
        <apexchart
          v-else
          type="area"
          height="280"
          :series="chartSeries"
          :options="chartOptions"
        />
      </div>

      <!-- Summary Stats -->
      <div v-if="!loading && !error && !hasNoData" class="summary-stats row q-mt-md q-gutter-md">
        <div class="col stat-card">
          <div class="stat-value text-primary">{{ summary.totalLogins }}</div>
          <div class="stat-label text-grey-7">{{ $t('total_logins') }}</div>
        </div>
        <div class="col stat-card">
          <div class="stat-value text-secondary">{{ summary.uniqueUsers }}</div>
          <div class="stat-label text-grey-7">{{ $t('unique_users') }}</div>
        </div>
        <div class="col stat-card">
          <div class="stat-value text-accent">{{ summary.avgLoginsPerDay }}</div>
          <div class="stat-label text-grey-7">{{ $t('avg_per_day') }}</div>
        </div>
      </div>
    </q-card-section>
  </q-card>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import VueApexCharts from 'vue3-apexcharts';
import type { LoginAnalyticsResponse } from 'src/types/loginAnalytics';

export default defineComponent({
  name: 'LoginActivityChart',

  components: {
    apexchart: VueApexCharts,
  },

  props: {
    analyticsData: {
      type: Object as () => LoginAnalyticsResponse | null,
      default: null,
    },
    loading: {
      type: Boolean,
      default: false,
    },
    error: {
      type: String,
      default: '',
    },
  },

  computed: {
    hasNoData(): boolean {
      if (!this.analyticsData?.data) return true;
      return this.analyticsData.data.length === 0 ||
        this.analyticsData.data.every(d => d.total_logins === 0);
    },

    summary(): { totalLogins: number; uniqueUsers: number; avgLoginsPerDay: string } {
      if (!this.analyticsData?.summary) {
        return {
          totalLogins: 0,
          uniqueUsers: 0,
          avgLoginsPerDay: '0',
        };
      }
      return {
        totalLogins: this.analyticsData.summary.total_logins,
        uniqueUsers: this.analyticsData.summary.unique_users,
        avgLoginsPerDay: this.analyticsData.summary.avg_logins_per_day.toFixed(1),
      };
    },

    chartSeries(): Array<{ name: string; data: number[] }> {
      if (!this.analyticsData?.data) return [];

      return [
        {
          name: this.$t('total_logins'),
          data: this.analyticsData.data.map(d => d.total_logins),
        },
        {
          name: this.$t('unique_users'),
          data: this.analyticsData.data.map(d => d.unique_users),
        },
      ];
    },

    isWeeklyAggregated(): boolean {
      return this.analyticsData?.aggregation === 'weekly';
    },

    rawDates(): string[] {
      return this.analyticsData?.data?.map(d => d.date) || [];
    },

    chartOptions(): Record<string, any> {
      const isDark = this.$q.dark.isActive;
      const currentLocale = this.$i18n.locale || 'en';
      const isWeekly = this.isWeeklyAggregated;

      const categories = this.analyticsData?.data?.map(d => {
        const date = new Date(d.date);

        // For weekly data, use middle of the week (start + 3 days) for positioning
        if (isWeekly) {
          date.setDate(date.getDate() + 3);
        }

        return date.toLocaleDateString(currentLocale, {
          month: 'short',
          day: 'numeric'
        });
      }) || [];

      return {
        chart: {
          id: 'loginActivityChart',
          toolbar: { show: false },
          background: 'transparent',
          zoom: { enabled: false },
        },
        theme: {
          mode: (isDark ? 'dark' : 'light') as 'dark' | 'light',
        },
        xaxis: {
          categories,
          labels: {
            style: {
              colors: isDark ? '#d2d2d2' : '#6b7280',
              fontSize: '11px',
            },
            rotate: -45,
            rotateAlways: categories.length > 14,
          },
        },
        yaxis: {
          labels: {
            style: {
              colors: isDark ? '#d2d2d2' : '#6b7280',
              fontSize: '12px',
            },
            formatter: (val: number) => Math.round(val).toString(),
          },
          min: 0,
        },
        stroke: {
          curve: 'smooth' as const,
          width: 2,
        },
        colors: ['#1976d2', '#26a69a'],
        fill: {
          type: 'gradient',
          gradient: {
            shade: isDark ? 'dark' : 'light',
            shadeIntensity: 0.5,
            opacityFrom: 0.5,
            opacityTo: 0.1,
            stops: [0, 90, 100],
          },
        },
        tooltip: {
          theme: isDark ? 'dark' : 'light',
          shared: true,
          intersect: false,
          x: {
            formatter: (_val: number, opts: { dataPointIndex: number }) => {
              const dateStr = this.rawDates[opts.dataPointIndex];
              if (!dateStr) return '';

              // For weekly data, show date range
              if (this.isWeeklyAggregated) {
                return this.formatDateRange(dateStr);
              }

              // For daily data, show single date
              const date = new Date(dateStr);
              return date.toLocaleDateString(currentLocale, {
                month: 'short',
                day: 'numeric'
              });
            },
          },
          y: {
            formatter: (val: number) => `${val}`,
          },
        },
        grid: {
          show: true,
          borderColor: isDark ? '#4b5563' : '#e5e7eb',
          strokeDashArray: 4,
          xaxis: { lines: { show: false } },
          yaxis: { lines: { show: true } },
        },
        legend: {
          position: 'top' as const,
          horizontalAlign: 'right' as const,
          labels: {
            colors: isDark ? '#d2d2d2' : '#6b7280',
          },
        },
        dataLabels: {
          enabled: false,
        },
      };
    },
  },

  methods: {
    formatDateRange(dateStr: string): string {
      const currentLocale = this.$i18n.locale || 'en';
      const startDate = new Date(dateStr);
      const endDate = new Date(startDate);
      endDate.setDate(endDate.getDate() + 6);

      const startFormatted = startDate.toLocaleDateString(currentLocale, {
        month: 'short',
        day: 'numeric'
      });
      const endFormatted = endDate.toLocaleDateString(currentLocale, {
        month: 'short',
        day: 'numeric'
      });

      return `${startFormatted} - ${endFormatted}`;
    },
  },
});
</script>

