<template>
  <div class="container">
    <div class="login-analytics-content">
      <!-- Header with title and time filter -->
      <div class="row items-center justify-between q-mt-md q-mb-md">
        <div>
          <h5 class="q-ma-none text-weight-medium">
            {{ $t('organization_login_activity') }}
          </h5>
          <p class="text-grey-7 q-mb-none q-mt-xs">
            {{ $t('login_analytics_description') }}
          </p>
        </div>
        <LoginTimeFilter @time-changed="handleTimeChange" />
      </div>

      <!-- Date Info Card -->
      <q-card class="q-mb-md info-card" v-if="!loading && analyticsData">
        <q-card-section>
          <div class="text-subtitle2 text-weight-medium q-mb-sm">
            <q-icon name="info" class="q-mr-xs" />
            {{ $t('data_info') }}
          </div>
          <div class="text-body2 text-grey-7">
            {{ $t('showing_data_from') }}
            <strong>{{ formatDateAccordingToPreference(analyticsData.start_date, true) }}</strong>
            {{ $t('to') }}
            <strong>{{ formatDateAccordingToPreference(analyticsData.end_date, true) }}</strong>
          </div>
        </q-card-section>
      </q-card>

      <!-- Main Chart -->
      <LoginActivityChart
        :analytics-data="analyticsData"
        :loading="loading"
        :error="error"
      />
    </div>
  </div>

  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import Loader from 'components/Loader.vue';
import LoginActivityChart from 'src/components/Settings/Users/LoginActivityChart.vue';
import LoginTimeFilter from 'src/components/Settings/Users/LoginTimeFilter.vue';
import { loginAnalyticsService } from 'src/services';
import type { LoginAnalyticsResponse } from 'src/types/loginAnalytics';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import dateUtils from 'src/utils/date';
export default defineComponent({
  name: 'LoginAnalyticsPage',

  components: {
    Loader,
    LoginActivityChart,
    LoginTimeFilter,
  },

  mixins: [helperMixin, dateUtils],

  data() {
    return {
      analyticsData: null as LoginAnalyticsResponse | null,
      loading: false,
      error: '',
    };
  },

  methods: {
    async fetchAnalytics(startDate: string, endDate: string) {
      this.loading = true;
      this.error = '';

      try {
        const response = await loginAnalyticsService.getLoginAnalytics(startDate, endDate);
        this.analyticsData = response;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        this.error = msg;
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    handleTimeChange(timeRange: { start_date: string; end_date: string }) {
      this.fetchAnalytics(timeRange.start_date, timeRange.end_date);
    },
  },
});
</script>

