<template>
  <q-btn-toggle
    v-model="selectedTime"
    toggle-color="primary"
    class="login-time-filter dashboard-text-color back-white"
    :ripple="false"
    :options="timeOptions"
    @update:model-value="onTimeChange"
  />

  <q-menu
    v-model="showDatePicker"
    no-parent-event
    anchor="bottom right"
    self="top right"
  >
    <div class="q-pa-md">
      <q-date
        v-model="customDateRange"
        minimal
        range
        :options="dateOptions"
      >
        <div class="row items-center justify-end q-gutter-sm">
          <q-btn
            v-close-popup
            flat
            :label="$t('cancel')"
            color="grey"
          />
          <q-btn
            v-close-popup
            :label="$t('apply')"
            color="primary"
            :disable="!isValidRange"
            @click="applyCustomRange"
          />
        </div>
      </q-date>
    </div>
  </q-menu>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

export interface TimeRange {
  start_date: string;
  end_date: string;
}

export default defineComponent({
  name: 'LoginTimeFilter',

  props: {
    defaultPeriod: {
      type: String,
      default: 'last_30_days',
      validator: (value: string) => [
        'last_7_days',
        'last_30_days',
        'last_90_days',
        'last_180_days',
        'last_365_days',
        'custom',
      ].includes(value),
    },
  },

  emits: ['time-changed'],

  data() {
    return {
      selectedTime: this.defaultPeriod,
      showDatePicker: false,
      customDateRange: null as { from: string; to: string } | string | null,
      lastCustomRange: null as TimeRange | null,
      timeMapping: {
        'last_7_days': 7,
        'last_30_days': 30,
        'last_90_days': 90,
        'last_180_days': 180,
        'last_365_days': 365,
      } as Record<string, number>,
    };
  },

  computed: {
    timeOptions(): Array<{ label: string; value: string }> {
      return [
        { label: this.$t('7_days'), value: 'last_7_days' },
        { label: this.$t('30_days'), value: 'last_30_days' },
        { label: this.$t('3_months'), value: 'last_90_days' },
        { label: this.$t('6_months'), value: 'last_180_days' },
        { label: this.$t('year'), value: 'last_365_days' },
        { label: this.$t('custom'), value: 'custom' },
      ];
    },

    isValidRange(): boolean {
      if (!this.customDateRange) return false;
      if (typeof this.customDateRange === 'object') {
        return Boolean(this.customDateRange.from && this.customDateRange.to);
      }
      return typeof this.customDateRange === 'string';
    },
  },

  mounted() {
    const range = this.calculateDateRange(this.defaultPeriod);
    this.emitTimeChange(range);
  },

  methods: {
    dateOptions(date: string): boolean {
      const today = new Date();
      today.setHours(23, 59, 59, 999);
      const [y, m, d] = date.split('/').map(Number);
      const checkDate = new Date(y, (m ?? 1) - 1, d ?? 1);
      return checkDate <= today;
    },

    calculateDateRange(period: string): TimeRange {
      const today = new Date();
      const endDate = today.toISOString().split('T')[0];

      const days = this.timeMapping[period];
      const startDate = new Date(today);
      startDate.setDate(startDate.getDate() - days);

      return {
        start_date: startDate.toISOString().split('T')[0],
        end_date: endDate,
      };
    },

    emitTimeChange(range: TimeRange) {
      this.$emit('time-changed', range);
    },

    onTimeChange(value: string) {
      if (value === 'custom') {
        this.showDatePicker = true;
        return;
      }

      const range = this.calculateDateRange(value);
      this.emitTimeChange(range);
    },

    applyCustomRange() {
      if (!this.customDateRange) return;

      let startDate: string;
      let endDate: string;

      if (typeof this.customDateRange === 'object') {
        startDate = this.customDateRange.from.replace(/\//g, '-');
        endDate = this.customDateRange.to.replace(/\//g, '-');
      } else {
        startDate = this.customDateRange.replace(/\//g, '-');
        endDate = startDate;
      }

      const range = { start_date: startDate, end_date: endDate };
      this.lastCustomRange = range;
      this.emitTimeChange(range);
    },
  },
});
</script>

